   T_Bremse : TOF;   // Bremse nachlaufen
END_VAR
BEGIN
NETWORK Selbsthaltung
(#Start OR #Laeuft) AND NOT #Stopp AND #Freigabe => #Laeuft;

NETWORK Bremse
#Laeuft AND TOF(#T_Bremse, T#1S) => #Bremse_Auf;
END_FUNCTION_BLOCK

k14_betriebsart.FC_Betriebsart:
