k14_boss.FB_Station:
FUNCTION_BLOCK "FB_Station"
VAR_INPUT
   Tuer_Zu : Bool;
   Seil_OK : Bool;
   Not_Halt_OK : Bool;
   Wind_OK : Bool;
   Quittieren : Bool;
   S_Start : Bool;
   S_Stopp : Bool;
   S_Tuer : Bool;
END_VAR
VAR_OUTPUT
   Antrieb : Bool;
   Bremse_Auf : Bool;
   Tuer_Auf : Bool;
   Stoerung : Bool;
END_VAR
VAR
   Kette : "FB_Kette";
   Fahrt : "FB_Antrieb";
   Tuer : "FB_Tuer";
END_VAR
VAR_TEMP
   Stillstand : Bool;   // Antrieb stand im letzten Zyklus
   Tuer_OK : Bool;   // Kettenglied Tür
   Fahrt_frei : Bool;
END_VAR
BEGIN
NETWORK Stillstand
NOT #Antrieb => #Stillstand;

NETWORK Tuerglied
#Tuer_Zu OR #Stillstand => #Tuer_OK;

NETWORK Sicherheitskette
=> #Kette(Tuer_Zu := #Tuer_OK, Seil_OK := #Seil_OK, Not_Halt_OK := #Not_Halt_OK, Wind_OK := #Wind_OK, Quittieren := #Quittieren);

NETWORK Fahrfreigabe
#Kette.OK AND #Tuer_Zu => #Fahrt_frei;

NETWORK Antrieb
=> #Fahrt(Start := #S_Start, Stopp := #S_Stopp, Freigabe := #Fahrt_frei, Laeuft => #Antrieb, Bremse_Auf => #Bremse_Auf);

NETWORK Tuer
=> #Tuer(Oeffnen := #S_Tuer, Endlage_Zu := #Tuer_Zu, Freigabe := #Stillstand, Quittieren := #Quittieren, Tuer_Auf => #Tuer_Auf);

NETWORK Sammelstoerung
#Kette.Fehler OR #Tuer.Stoerung => #Stoerung;
END_FUNCTION_BLOCK

