k15_ablauf.FB_Ablauf:
FUNCTION_BLOCK "FB_Ablauf"
VAR_INPUT
   S_Abfahrt : Bool;
   Ankunft : Bool;
   Kette_OK : Bool;
END_VAR
VAR_OUTPUT
   Tuer_Auf : Bool;
   Hupe : Bool;
   Fahrt : Bool;
   Halt : Bool;
END_VAR
VAR_IN_OUT
   Fahrten : Int;   // Fahrtenzähler
END_VAR
VAR
   Schritt_Einsteigen : Bool;
   Schritt_Warnen : Bool;
   Schritt_Fahrt : Bool;
   T_Warnen : TON;
END_VAR
BEGIN
NETWORK Grundstellung
NOT #Schritt_Einsteigen AND NOT #Schritt_Warnen AND NOT #Schritt_Fahrt => S #Schritt_Einsteigen;

NETWORK Einsteigen -> Warnen
#Schritt_Einsteigen AND #S_Abfahrt AND #Kette_OK => S #Schritt_Warnen, R #Schritt_Einsteigen;

NETWORK Warnen -> Fahrt
#Schritt_Warnen AND TON(#T_Warnen, T#2S) => S #Schritt_Fahrt, R #Schritt_Warnen, INC(#Fahrten);

NETWORK Fahrt -> Einsteigen
#Schritt_Fahrt AND #Ankunft => S #Schritt_Einsteigen, R #Schritt_Fahrt;

NETWORK Kette offen
NOT #Kette_OK AND (#Schritt_Warnen OR #Schritt_Fahrt) => S #Schritt_Einsteigen, R #Schritt_Warnen, R #Schritt_Fahrt;

NETWORK Einsteigen
#Schritt_Einsteigen => #Tuer_Auf, #Halt;

NETWORK Vorwarnung
#Schritt_Warnen => #Hupe;

NETWORK Fahrt
#Schritt_Fahrt => #Fahrt;
END_FUNCTION_BLOCK

